/* Attd13Mapper.selectNextChangeReqId */
SELECT CONCAT('LC', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'LEAVE_CHANGE_REQ_ID'))
  FROM DUAL

/* Attd13Mapper.countLeaveUseOnDate */
SELECT COUNT(*)
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD     = #{cmpnyCd}
   AND U.USER_CD      = #{userCd}
   AND U.LEAVE_CD     = #{leaveCd}
   AND U.START_DATE   = #{targetDate}
   AND U.LEAVE_ID    != #{excludeLeaveId}
   AND U.LEAVE_STATUS = 'CONFIRMED'
   AND U.DEL_YN       = 'N'

/* Attd13Mapper.selectGrantAvailToDate */
SELECT G.AVAIL_TO_DATE
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD = #{cmpnyCd}
   AND G.GRANT_ID = #{grantId}
 LIMIT 1

mapper.insert:
/* Attd13Mapper.insertChangeRequest */
INSERT INTO TB_LEAVE_CHANGE_REQUEST (
      CHANGE_REQ_ID
    , CMPNY_CD
    , SITE_CD
    , TARGET_USER_CD
    , TARGET_LEAVE_ID
    , INITIATOR_TYPE
    , REQ_TYPE
    , MOVE_TARGET_DATE
    , REQ_REASON
    , WORKER_RESPONSE
    , REQ_STATUS
    , INITIATOR_USER_CD
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
      #{changeReqId}
    , #{cmpnyCd}
    , #{siteCd}
    , #{targetUserCd}
    , #{targetLeaveId}
    , #{initiatorType}
    , #{reqType}
    , #{moveTargetDate}
    , #{reqReason}
    , 'PENDING'
    , 'REQUESTED'
    , #{initiatorUserCd}
    , 'N'
    , #{insertNo}
    , NOW()
)

mapper.select:
/* Attd13Mapper.selectChangeRequests */ SELECT R.CHANGE_REQ_ID AS changeReqId , R.CMPNY_CD AS cmpnyCd , R.SITE_CD AS siteCd , R.TARGET_USER_CD AS targetUserCd , TU.USER_NM AS targetUserNm , R.TARGET_LEAVE_ID AS targetLeaveId , LU.START_DATE AS targetStartDate , R.INITIATOR_TYPE AS initiatorType , R.REQ_TYPE AS reqType , R.MOVE_TARGET_DATE AS moveTargetDate , R.REQ_REASON AS reqReason , R.WORKER_RESPONSE AS workerResponse , R.RESPONSE_REASON AS responseReason , R.REJECT_REASON AS rejectReason , R.REQ_STATUS AS reqStatus , R.INITIATOR_USER_CD AS initiatorUserCd , R.CONFIRM_USER_CD AS confirmUserCd , DATE_FORMAT(R.CONFIRM_DATE, '%Y%m%d%H%i%s') AS confirmDate , DATE_FORMAT(R.INSERT_DATE, '%Y%m%d%H%i%s') AS insertDate FROM TB_LEAVE_CHANGE_REQUEST R LEFT JOIN TB_USER TU ON TU.CMPNY_CD = R.CMPNY_CD AND TU.USER_CD = R.TARGET_USER_CD LEFT JOIN TB_USER_LEAVE_USE LU ON LU.CMPNY_CD = R.CMPNY_CD AND LU.LEAVE_ID = R.TARGET_LEAVE_ID WHERE R.CMPNY_CD = #{cmpnyCd} AND R.DEL_YN = 'N'
AND R.SITE_CD = #{siteCd}
AND R.REQ_STATUS = #{reqStatus}
AND TU.USER_NM LIKE CONCAT('%', #{userNm}, '%')
AND R.TARGET_USER_CD IN ( SELECT NU.USER_CD FROM TB_USER NU WHERE NU.CMPNY_CD = #{cmpnyCd} AND NU.SITE_CD = #{siteCd}
AND NU.NODE_CD IN ( WITH RECURSIVE sub AS ( SELECT N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{cmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd} UNION ALL SELECT C.NODE_CD FROM TB_SITE_NODE C JOIN sub S2 ON C.CMPNY_CD = #{cmpnyCd} AND C.SITE_CD = #{siteCd} AND C.PARENT_NODE_CD = S2.NODE_CD ) SELECT NODE_CD FROM sub )
AND NU.NODE_CD = #{nodeCd}
)
ORDER BY R.INSERT_DATE DESC, R.CHANGE_REQ_ID DESC

mapper.update:
/* Attd13Mapper.applyWorkerResponse */
UPDATE TB_LEAVE_CHANGE_REQUEST
   SET WORKER_RESPONSE = #{workerResponse}
     , RESPONSE_REASON = #{responseReason}
     , REQ_STATUS      = #{reqStatus}
     , UPDATE_NO       = #{updateNo}
     , UPDATE_DATE     = NOW()
 WHERE CMPNY_CD       = #{cmpnyCd}
   AND CHANGE_REQ_ID  = #{changeReqId}
   AND TARGET_USER_CD = #{targetUserCd}
   AND REQ_STATUS     = 'REQUESTED'
   AND DEL_YN         = 'N'

/* Attd13Mapper.confirmChangeRequest */
UPDATE TB_LEAVE_CHANGE_REQUEST
   SET REQ_STATUS      = 'CONFIRMED'
     , CONFIRM_USER_CD = #{confirmUserCd}
     , CONFIRM_DATE    = NOW()
     , UPDATE_NO       = #{confirmUserCd}
     , UPDATE_DATE     = NOW()
 WHERE CMPNY_CD      = #{cmpnyCd}
   AND CHANGE_REQ_ID = #{changeReqId}
   AND REQ_STATUS    = 'AGREED'
   AND DEL_YN        = 'N'

/* Attd13Mapper.rejectChangeRequest */
UPDATE TB_LEAVE_CHANGE_REQUEST
   SET REQ_STATUS      = 'REJECTED'
     , REJECT_REASON   = #{rejectReason}
     , CONFIRM_USER_CD = #{confirmUserCd}
     , CONFIRM_DATE    = NOW()
     , UPDATE_NO       = #{confirmUserCd}
     , UPDATE_DATE     = NOW()
 WHERE CMPNY_CD      = #{cmpnyCd}
   AND CHANGE_REQ_ID = #{changeReqId}
   AND REQ_STATUS    = 'AGREED'
   AND DEL_YN        = 'N'

/* Attd13Mapper.moveLeaveUseDate */
UPDATE TB_USER_LEAVE_USE
   SET ORIG_DESIGNATED_DATE = IFNULL(ORIG_DESIGNATED_DATE, START_DATE)
     , START_DATE           = #{newDate}
     , END_DATE             = #{newDate}
     , UPDATE_NO            = #{updateNo}
     , UPDATE_DATE          = NOW()
 WHERE CMPNY_CD     = #{cmpnyCd}
   AND LEAVE_ID     = #{leaveId}
   AND LEAVE_STATUS = 'CONFIRMED'
   AND DEL_YN       = 'N'

/* Attd13Mapper.cancelLeaveUse */
UPDATE TB_USER_LEAVE_USE
   SET LEAVE_STATUS  = 'CANCELLED'
     , CANCEL_REASON = #{cancelReason}
     , CANCEL_DATE   = NOW()
     , UPDATE_NO     = #{updateNo}
     , UPDATE_DATE   = NOW()
 WHERE CMPNY_CD     = #{cmpnyCd}
   AND LEAVE_ID     = #{leaveId}
   AND LEAVE_STATUS = 'CONFIRMED'
   AND DEL_YN       = 'N'

