/* Attd13Mapper.deleteWorkPlanLeave */
DELETE FROM TB_USER_WORK_PLAN
 WHERE CMPNY_CD     = #{cmpnyCd}
   AND SITE_CD      = #{siteCd}
   AND USER_CD      = #{userCd}
   AND WORK_YMD     = #{workYmd}
   AND WORK_PLAN_CD = #{leaveCd}

