    , SITE_CD
    , USER_CD
    , WORK_YMD
    , WORK_PLAN_CD
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
VALUES (
      #{cmpnyCd}
    , #{siteCd}
    , #{userCd}
    , #{workYmd}
    , #{leaveCd}
    , #{updateNo}
    , NOW()
    , #{updateNo}
    , NOW()
)
ON DUPLICATE KEY UPDATE
      WORK_PLAN_CD = #{leaveCd}
    , UPDATE_NO    = #{updateNo}
    , UPDATE_DATE  = NOW()
